import 'server-only';
import { createHash } from 'node:crypto';
import type { ContentStatus, Locale, Prisma } from '@prisma/client';
import { db } from '@/lib/db';
import { TranslationConfigError, TranslationProviderError, isTranslationConfigured, translateHtml, translationConfig } from './google';
import { prepareSegment, restoreSegment } from './protect';
import { repairText } from '@/lib/meridian/text';

/*
 * Automatic translation of CMS content. English is the only source of truth:
 * after an English save the gu/hi rows are regenerated by Google Cloud
 * Translation. This module never writes the EN row.
 *
 *  - Source hash: a hash of the English fields. When English changes, the
 *    state becomes STALE (the old translation stays live) until regenerated.
 *  - Failures keep the last good translation and record a safe error message.
 *  - A hand-written gu/hi row found before the first machine run is copied to
 *    legacyBackup (status LEGACY) before it is replaced.
 */

export const TARGET_LOCALES = ['GU', 'HI'] as const satisfies readonly Locale[];
const GOOGLE_CODE: Record<(typeof TARGET_LOCALES)[number], string> = { GU: 'gu', HI: 'hi' };

export type TranslatableType = 'Page' | 'BlogPost' | 'Notice' | 'Event' | 'Announcement' | 'GalleryAlbum';
type Kind = 'text' | 'html';
type Fields = Record<string, string | null>;

interface Source {
  /** Translatable English fields (null/empty fields are skipped and copied as null). */
  fields: Fields;
  kinds: Record<string, Kind>;
  /** Existing rows per target locale (for the legacy backup). */
  existing: Partial<Record<Locale, unknown>>;
  /** Writes one translated locale. `extra` holds fields stored on the state row. */
  write: (locale: Locale, fields: Fields) => Promise<Prisma.InputJsonValue | null>;
}

const t = (value: string | null | undefined) => (value && value.trim() ? value : null);

/** Field kinds; any field not listed is plain text. */
const HTML_FIELDS = new Set(['bodyHtml', 'description']);

function kindsFor(fields: Fields, overrides: Record<string, Kind> = {}): Record<string, Kind> {
  return Object.fromEntries(Object.keys(fields).map((key) => [key, overrides[key] ?? (HTML_FIELDS.has(key) ? 'html' : 'text')]));
}

async function loadSource(type: TranslatableType, id: string): Promise<Source | null> {
  switch (type) {
    case 'Page': {
      const page = await db.page.findUnique({ where: { id }, include: { translations: true } });
      const en = page?.translations.find((row) => row.locale === 'EN');
      if (!page || !en) return null;
      const fields = { title: en.title, summary: t(en.summary), bodyHtml: t(en.bodyHtml), seoTitle: t(en.seoTitle), seoDescription: t(en.seoDescription) };
      const status: ContentStatus = en.status;
      return {
        fields,
        kinds: kindsFor(fields),
        existing: Object.fromEntries(page.translations.filter((row) => row.locale !== 'EN').map((row) => [row.locale, row])),
        write: async (locale, out) => {
          const data = { title: out.title ?? en.title, summary: out.summary, bodyHtml: out.bodyHtml ?? '', seoTitle: out.seoTitle, seoDescription: out.seoDescription, status };
          await db.pageTranslation.upsert({ where: { pageId_locale: { pageId: id, locale } }, create: { pageId: id, locale, ...data }, update: data });
          return null;
        },
      };
    }
    case 'BlogPost': {
      const post = await db.blogPost.findUnique({ where: { id }, include: { translations: true } });
      const en = post?.translations.find((row) => row.locale === 'EN');
      if (!post || !en) return null;
      const fields = { title: en.title, summary: t(en.summary), bodyHtml: t(en.bodyHtml) };
      return {
        fields,
        kinds: kindsFor(fields),
        existing: Object.fromEntries(post.translations.filter((row) => row.locale !== 'EN').map((row) => [row.locale, row])),
        write: async (locale, out) => {
          const data = { title: out.title ?? en.title, summary: out.summary, bodyHtml: out.bodyHtml ?? '' };
          await db.blogTranslation.upsert({ where: { postId_locale: { postId: id, locale } }, create: { postId: id, locale, ...data }, update: data });
          return null;
        },
      };
    }
    case 'Notice': {
      const notice = await db.notice.findUnique({ where: { id }, include: { translations: true } });
      const en = notice?.translations.find((row) => row.locale === 'EN');
      if (!notice || !en) return null;
      const fields = { title: en.title, bodyHtml: t(en.bodyHtml), linkLabel: t(en.linkLabel) };
      return {
        fields,
        kinds: kindsFor(fields),
        existing: Object.fromEntries(notice.translations.filter((row) => row.locale !== 'EN').map((row) => [row.locale, row])),
        write: async (locale, out) => {
          // The link itself is an identifier: copied, never translated.
          const data = { title: out.title ?? en.title, bodyHtml: out.bodyHtml ?? '', linkLabel: out.linkLabel, linkUrl: en.linkUrl };
          await db.noticeTranslation.upsert({ where: { noticeId_locale: { noticeId: id, locale } }, create: { noticeId: id, locale, ...data }, update: data });
          return null;
        },
      };
    }
    case 'Event': {
      const event = await db.event.findUnique({ where: { id }, include: { translations: true } });
      const en = event?.translations.find((row) => row.locale === 'EN');
      if (!event || !en) return null;
      const fields = { title: en.title, description: t(en.description), location: t(en.location) };
      return {
        fields,
        kinds: kindsFor(fields),
        existing: Object.fromEntries(event.translations.filter((row) => row.locale !== 'EN').map((row) => [row.locale, row])),
        write: async (locale, out) => {
          const data = { title: out.title ?? en.title, description: out.description ?? '', location: out.location };
          await db.eventTranslation.upsert({ where: { eventId_locale: { eventId: id, locale } }, create: { eventId: id, locale, ...data }, update: data });
          return null;
        },
      };
    }
    case 'Announcement': {
      const item = await db.announcement.findUnique({ where: { id }, include: { translations: true } });
      const en = item?.translations.find((row) => row.locale === 'EN');
      if (!item || !en) return null;
      const fields = { title: en.title, message: t(en.message), linkLabel: t(en.linkLabel) };
      return {
        fields,
        kinds: kindsFor(fields),
        existing: Object.fromEntries(item.translations.filter((row) => row.locale !== 'EN').map((row) => [row.locale, row])),
        write: async (locale, out) => {
          const data = { title: out.title ?? en.title, message: out.message ?? en.message, linkLabel: out.linkLabel };
          await db.announcementTranslation.upsert({
            where: { announcementId_locale: { announcementId: id, locale } },
            create: { announcementId: id, locale, ...data },
            update: data,
          });
          return null;
        },
      };
    }
    case 'GalleryAlbum': {
      const album = await db.galleryAlbum.findUnique({ where: { id }, include: { translations: true, items: { orderBy: { sortOrder: 'asc' } } } });
      const en = album?.translations.find((row) => row.locale === 'EN');
      if (!album || !en) return null;
      // Photo captions/alt text have no locale table: they are translated too
      // and stored on the state row (fields.items[mediaId]).
      const fields: Fields = { title: en.title, description: t(en.description) };
      for (const item of album.items) {
        fields[`caption:${item.mediaId}`] = t(item.caption);
        fields[`alt:${item.mediaId}`] = t(item.altText);
      }
      return {
        fields,
        kinds: kindsFor(fields),
        existing: Object.fromEntries(album.translations.filter((row) => row.locale !== 'EN').map((row) => [row.locale, row])),
        write: async (locale, out) => {
          const data = { title: out.title ?? en.title, description: out.description };
          await db.albumTranslation.upsert({ where: { albumId_locale: { albumId: id, locale } }, create: { albumId: id, locale, ...data }, update: data });
          const items: Record<string, { caption: string | null; alt: string | null }> = {};
          for (const item of album.items) items[item.mediaId] = { caption: out[`caption:${item.mediaId}`] ?? null, alt: out[`alt:${item.mediaId}`] ?? null };
          return { items };
        },
      };
    }
  }
}

export function sourceHash(fields: Fields): string {
  const ordered = Object.keys(fields)
    .sort()
    .map((key) => [key, fields[key]]);
  return createHash('sha256').update(JSON.stringify(ordered)).digest('hex').slice(0, 32);
}

/** Error text safe to show in the admin (never a raw provider response or credential). */
function safeError(error: unknown): string {
  if (error instanceof TranslationConfigError || error instanceof TranslationProviderError) return error.message;
  return 'Translation failed unexpectedly. Try again later.';
}

export interface TranslateResult {
  locale: Locale;
  outcome: 'translated' | 'unchanged' | 'not-configured' | 'failed' | 'skipped';
  message?: string;
}

/**
 * Brings gu/hi up to date with the English source. With `force`, regenerates
 * even when English is unchanged (the admin "Regenerate" action).
 */
export async function translateEntity(type: TranslatableType, id: string, options: { force?: boolean } = {}): Promise<TranslateResult[]> {
  const source = await loadSource(type, id);
  if (!source) return TARGET_LOCALES.map((locale) => ({ locale, outcome: 'skipped' as const, message: 'No English source.' }));
  const hash = sourceHash(source.fields);
  const results: TranslateResult[] = [];

  for (const locale of TARGET_LOCALES) {
    const key = { entityType: type, entityId: id, locale };
    let state = await db.translationState.findUnique({ where: { entityType_entityId_locale: key } });
    if (!state) {
      const legacy = source.existing[locale];
      state = await db.translationState.create({
        data: {
          ...key,
          status: legacy ? 'LEGACY' : 'PENDING',
          latestHash: hash,
          legacyBackup: legacy ? (JSON.parse(JSON.stringify(legacy)) as Prisma.InputJsonValue) : undefined,
          provider: legacy ? 'manual' : null,
        },
      });
    }
    if (!options.force && state.status === 'DONE' && state.sourceHash === hash && source.existing[locale]) {
      results.push({ locale, outcome: 'unchanged' });
      continue;
    }
    // English changed since the last good translation: mark stale (old text stays live).
    if (state.status === 'DONE' && state.sourceHash !== hash) {
      state = await db.translationState.update({ where: { id: state.id }, data: { status: 'STALE', latestHash: hash } });
    } else if (state.latestHash !== hash) {
      state = await db.translationState.update({ where: { id: state.id }, data: { latestHash: hash } });
    }

    if (!isTranslationConfigured()) {
      let message = 'Automatic translation is not configured.';
      try {
        translationConfig();
      } catch (error) {
        message = safeError(error);
      }
      await db.translationState.update({ where: { id: state.id }, data: { lastError: message } });
      results.push({ locale, outcome: 'not-configured', message });
      continue;
    }

    const keys = Object.keys(source.fields).filter((field) => source.fields[field]);
    try {
      const { provider, texts } = await translateHtml(
        // Legacy imports contain mojibake (â€™ …); translate the repaired English.
        keys.map((field) => prepareSegment(repairText(source.fields[field]) || source.fields[field]!, source.kinds[field])),
        GOOGLE_CODE[locale],
      );
      const out: Fields = Object.fromEntries(Object.keys(source.fields).map((field) => [field, null]));
      keys.forEach((field, i) => {
        out[field] = restoreSegment(texts[i], source.kinds[field]);
      });
      const extra = await source.write(locale, out);
      await db.translationState.update({
        where: { id: state.id },
        data: {
          status: 'DONE',
          sourceHash: hash,
          latestHash: hash,
          provider,
          attempts: { increment: 1 },
          lastError: null,
          translatedAt: new Date(),
          fields: extra ?? undefined,
        },
      });
      results.push({ locale, outcome: 'translated' });
    } catch (error) {
      const message = safeError(error);
      // The previous translation row is left untouched (last good version).
      await db.translationState.update({ where: { id: state.id }, data: { status: 'FAILED', attempts: { increment: 1 }, lastError: message } });
      results.push({ locale, outcome: 'failed', message });
    }
  }
  return results;
}

/**
 * Called after an English save. Runs after the response is sent (next/server
 * `after`), so publishing never waits for — or fails because of — translation.
 */
export async function scheduleTranslation(type: TranslatableType, id: string): Promise<void> {
  const run = () =>
    translateEntity(type, id).catch((error) => {
      console.error(`[translation] ${type} ${id}: ${error instanceof Error ? error.message : 'failed'}`);
    });
  try {
    const { after } = await import('next/server');
    after(run);
  } catch {
    await run();
  }
}

/** Every translatable entity id, for the admin "translate everything" backfill. */
export async function listTranslatableEntities(): Promise<Array<{ type: TranslatableType; id: string }>> {
  const [pages, posts, notices, events, announcements, albums] = await Promise.all([
    db.page.findMany({ select: { id: true } }),
    db.blogPost.findMany({ select: { id: true } }),
    db.notice.findMany({ select: { id: true } }),
    db.event.findMany({ select: { id: true } }),
    db.announcement.findMany({ select: { id: true } }),
    db.galleryAlbum.findMany({ select: { id: true } }),
  ]);
  return [
    ...pages.map(({ id }) => ({ type: 'Page' as const, id })),
    ...posts.map(({ id }) => ({ type: 'BlogPost' as const, id })),
    ...notices.map(({ id }) => ({ type: 'Notice' as const, id })),
    ...events.map(({ id }) => ({ type: 'Event' as const, id })),
    ...announcements.map(({ id }) => ({ type: 'Announcement' as const, id })),
    ...albums.map(({ id }) => ({ type: 'GalleryAlbum' as const, id })),
  ];
}
